)
and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) or pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND T2.ENTRUST_ID like CONCAT_WS('', '%', #{entrustId}, '%')
AND T1.FINPROD_ID like CONCAT_WS('', '%', #{finprodId}, '%')
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.PS = #{ps}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
