UNION ALL SELECT #{VALID_STATUS_03} validStatus, null workflowId, null workflowStatus, T1.TOTLE_TRADE_ID busiCode, T2.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, T3.FINPROD_ID finprodId, T3.FINPROD_NAME finprodName, T1.PS ps,
CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS prinAmt, IFNULL(T4.PRIN_AMT,T5.PRIN_AMT) winlotteryAmt, T2.PURCH_DATE purchDate,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS tradeDate, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.SETTLE_DATE END AS settleDate, T2.PURCH_MODLE purchModle, T2.PURCH_TYPE purchType, T1.TRADE_MARKET tradeMarket, T1.CCY ccy, T1.REMARK remark FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05} AND T4.IS_CANCEL='N' LEFT JOIN TRD_PRODUCT_DEAL T5 ON T1.P_TRADE_ID = T5.TOTLE_TRADE_ID and T5.PS=#{PS_T05} AND T5.IS_CANCEL='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.TRADE_STATUS = #{VALID_STATUS_03}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND T1.PS IN
#{item}
AND (PP.PORTFOLIO_ID IN
null) or PP.PORTFOLIO_ID in (
#{item}
OR PP.PARENT_PORTFOLIO_ID IN
null) or PP.PARENT_PORTFOLIO_ID in (
#{item}
)
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND T2.ENTRUST_ID like CONCAT_WS('', '%', #{entrustId}, '%')
AND T1.FINPROD_ID like CONCAT_WS('', '%', #{finprodId}, '%')
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.PS = #{ps}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
AND T2.PURCH_DATE >= STR_TO_DATE(#{purchDateBegin}, '%Y-%m-%d')
AND T2.PURCH_DATE <= STR_TO_DATE(#{purchDateEnd}, '%Y-%m-%d')

mapper.select:
SELECT T2.ENTRUST_ID, T1.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T1.PS, T1.B_TRADE_ID, T1.TOTLE_TRADE_ID, T3.FINPROD_ID, T3.FINPROD_NAME, T1.TRADE_MARKET, T2.PURCH_MODLE, T2.PURCH_TYPE, T2.PURCH_DATE,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS TRADE_DATE, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.SETTLE_DATE END AS SETTLE_DATE, T1.CCY, T1.INV_AIM, T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID, CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS tradeAmt,
case when t1.ps=#{PS_T58} then t1.PRIN_AMT else IFNULL(T4.PRIN_AMT,T6.PRIN_AMT) end as winlotteryAmt, T2.DEPOSIT_AMT, IFNULL(t4.trade_Amt,t6.trade_Amt) supplementaryAmt,
case when t1.trade_amt < 0 then abs(t1.trade_amt) when t1.ps=#{PS_T58} then t1.trade_amt else 0 end as refundAmt, case when t1.trade_amt < 0 then t1.trade_date when t1.ps=#{PS_T58} then t1.trade_date else null end as refundDate, T1.REMARK, T1.TRADER, T1.COUNTER_ID, T1.COUNTER_TRADER, T1.COUNTER_CONTACT FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05}
LEFT JOIN TRD_PRODUCT_DEAL T6 ON T1.P_TRADE_ID = T6.TOTLE_TRADE_ID and T6.PS=#{PS_T05} and T6.IS_CANCEL ='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T1.TOTLE_TRADE_ID=#{tradeId}

SELECT T2.ENTRUST_ID, T1.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T1.PS, T1.B_TRADE_ID, T3.FINPROD_ID, T3.FINPROD_NAME, T1.TRADE_MARKET, T2.PURCH_MODLE, T2.PURCH_TYPE, T2.PURCH_DATE,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS TRADE_DATE, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.TRADE_DATE END AS SETTLE_DATE, T1.CCY, T1.INV_AIM, T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID, CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS tradeAmt,
IFNULL(T4.PRIN_AMT,T6.PRIN_AMT) winlotteryAmt, T2.DEPOSIT_AMT, IFNULL(t4.trade_Amt,t6.trade_Amt) supplementaryAmt,
case when t1.trade_amt < 0 then abs(t1.trade_amt) else 0 end as refundAmt, case when t1.trade_amt < 0 then t1.trade_date else null end as refundDate, T1.REMARK, T1.TRADER, T1.COUNTER_ID, T1.COUNTER_TRADER, T1.COUNTER_CONTACT FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05}
LEFT JOIN WFL_TRD_PRODUCT_DEAL T6 ON T1.P_TRADE_ID = T6.TOTLE_TRADE_ID and T6.PS=#{PS_T05} and T6.IS_CANCEL ='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T1.TOTLE_TRADE_ID=#{tradeId}

SELECT T2.ENTRUST_ID, T1.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T1.PS, T1.B_TRADE_ID, T3.FINPROD_ID, T3.FINPROD_NAME, T1.TRADE_MARKET, T2.PURCH_MODLE, T2.PURCH_TYPE, T2.PURCH_DATE,
CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_CFM_DATE ELSE T1.TRADE_DATE END AS TRADE_DATE, CASE WHEN T2.PURCH_TYPE=#{PURCH_TYPE_02} AND T1.PS=#{PS_T04} THEN T2.PUR_PAY_DATE ELSE T1.TRADE_DATE END AS SETTLE_DATE, T1.CCY, T1.INV_AIM, T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID, CASE WHEN T1.PS=#{PS_T04} THEN T1.PRIN_AMT ELSE T2.PUR_AMT END AS tradeAmt,
IFNULL(T5.PRIN_AMT,T6.PRIN_AMT) winlotteryAmt, T2.DEPOSIT_AMT, IFNULL(t4.trade_Amt,t6.trade_Amt) supplementaryAmt, t5.trade_date refundDate, t5.trade_amt refundAmt, T1.REMARK, T1.TRADER, T1.COUNTER_ID, T1.COUNTER_TRADER, T1.COUNTER_CONTACT FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T1.TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID and T4.PS=#{PS_T05} LEFT JOIN WFL_TRD_PRODUCT_DEAL T5 ON T1.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID and T5.PS=#{PS_T51} LEFT JOIN WFL_TRD_PRODUCT_DEAL T6 ON T1.P_TRADE_ID = T6.TOTLE_TRADE_ID and T6.PS=#{PS_T05} and T6.IS_CANCEL ='N' LEFT JOIN PTL_PORTFOLIO PP ON T1.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND T5.TRADE_ID=#{tradeId}

select.if:
SELECT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ( A.ACCT_NO LIKE CONCAT_WS('', '%', #{search}, '%') OR B.SEC_ACCT_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR concat_ws('', PORTFOLIO_ID , A.ACCT_NO) = #{initValue, jdbcType=VARCHAR} )
AND TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}

SELECT SEC_ACCT_ID hidCode, SEC_ACCT_ID code, SEC_ACCT_NAME name, SEC_ACCT_NAME shortName FROM STL_SEC_ACCT_INFO
( STL_SEC_ACCT_INFO.SEC_ACCT_ID LIKE CONCAT_WS('', '%', #{search}, '%') OR STL_SEC_ACCT_INFO.SEC_ACCT_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
AND STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{initValue, jdbcType=VARCHAR}

mapper.select:
SELECT
       100 - IFNULL(sum(fcp.PRIN_AMT), 0)
FROM
     FIN_CASH_PLAN fcp
     inner join FIN_CASH_INFO fci
     on fcp.CASH_ID = fci.CASH_ID
WHERE
    fcp.FINPROD_ID = #{finprodId}

    AND fcp.MDATE < #{settleDate}
    and fci.CASH_TYPE_1 = #{cashType1}

mapper.insert:
INSERT INTO TRD_PRODUCT_DEAL_ADD (TRADE_ID, PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) SELECT concat_ws('', TRADE_ID , 'R'), PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, #{updateUser}, CURRENT_TIMESTAMP FROM TRD_PRODUCT_DEAL_ADD where TRADE_ID = #{bizCode}
